    Box,
    { flexDirection: 'column', gap: 1 },
    h(Text, {}, 'Run this in your terminal, then answer the question.'),
    h(Code, { language: 'bash', source: card.command }),
    h(Button, {
      key: 'copy',
      label: 'Copy',
      onPress: (press) => copy($, card, press).catch(() => {}),
    }),
  );
}

